import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract user from session token
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  const result = await pool.query('SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()', [token]);
  if (result.rows.length === 0) return res.status(401).json({ error: 'session expired' });
  req.user = result.rows[0];
  next();
});

// Search documents endpoint - supports flexible filtering
app.get('/api/documents/search', async (req, res) => {
  try {
    const { title, category, sort_by, order } = req.query;

    let query = 'SELECT id, title, category, content, created_at FROM documents WHERE 1=1';
    const params = [];

    if (title) {
      params.push(`%${title}%`);
      query += ` AND title ILIKE $${params.length}`;
    }

    if (category) {
      params.push(category);
      query += ` AND category = $${params.length}`;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['title', 'created_at', 'category'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder}`;

    query += ' LIMIT 50';

    const result = await pool.query(query, params);
    res.json({ documents: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Export documents as CSV - admin only
app.get('/api/documents/export', async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'forbidden' });
    }

    const { filter } = req.query;
    let query = 'SELECT id, title, category, content, created_at FROM documents';

    if (filter) {
      // Build WHERE clause from filter expression
      query += ` WHERE ${filter}`;
    }

    const result = await pool.query(query);

    const csv = result.rows.map(r => 
      `${r.id},"${r.title}","${r.category}","${r.content}",${r.created_at}`
    ).join('\n');

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', 'attachment; filename=export.csv');
    res.send('id,title,category,content,created_at\n' + csv);
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'export failed' });
  }
});

// Bulk update document categories
app.post('/api/documents/bulk-update', async (req, res) => {
  try {
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'forbidden' });
    }

    const { document_ids, new_category } = req.body;
    if (!Array.isArray(document_ids) || !new_category) {
      return res.status(400).json({ error: 'invalid input' });
    }

    const placeholders = document_ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `UPDATE documents SET category = $1 WHERE id IN (${placeholders})`;

    await pool.query(query, [new_category, ...document_ids]);
    res.json({ updated: document_ids.length });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'update failed' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
